                sums.setdefault(r+c,Counter())[inp[r][c]]+=1
    A={k:v.most_common(1)[0][0] for k,v in sums.items()}
    # infer missing sums from periodicity: find period from known values
    ks=sorted(A)
    def Aof(s):
        if s in A: return A[s]
        # try periods 3..10, choose one consistent with known values
