            base=ks[0]
            if all(A.get(base+((s-base)%p)+p*t)==A[base+((s-base)%p)+p*t] for t in range(0,((ks[-1]-base)//p)+2) if base+((s-base)%p)+p*t in A):
                pass
        return None
    def f(grid):
        out=[row[:] for row in grid]
        for r in range(len(grid)):
            for c in range(len(grid[0])):
