        for p in range(3,11):
            ref=ks[0]
            ok=all(A.get(ref+((k-ref)%p)+p*t)==A[ref+((k-ref)%p)+p*t] for k in ks for t in [0] if True)
            # simpler: check A periodic with p on known keys
            ok=all(A[k]==A[ks[0]+(k-ks[0])%p] for k in ks)
            if ok:
                return A[ks[0]+(s-ks[0])%p]
        return None
    return f
